const express = require('express');
const Stripe = require('stripe');
const db = require('../db');

const app = express();
app.use(express.json());
const stripe = new Stripe(process.env.STRIPE_KEY);

app.post('/api/connect/bank-accounts/attach', async (req, res) => {
  const { stripeAccountId, bankToken } = req.body;

  // Verify ownership of the connected account in platform database
  const accountMapping = await db('vendor_stripe_accounts')
    .where({ stripe_account_id: stripeAccountId, user_id: req.user.id })
    .first();
  if (!accountMapping) {
    return res.status(403).json({ error: 'Unauthorized to modify external accounts for this merchant' });
  }

  try {
    const externalAccount = await stripe.accounts.createExternalAccount(
      stripeAccountId,
      { external_account: bankToken }
    );

    return res.json({
      status: 'Bank account added',
      bankId: externalAccount.id,
      last4: externalAccount.last4
    });
  } catch (err) {
    return res.status(500).json({ error: err.message });
  }
});

module.exports = app;
